    local function VM_000Ol(d, k, m)
        local R_01O111 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_01O111, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_01O111)
    end

    -- Execution Guard
    local F_I0OII = loadstring(VM_000Ol(B_lll01l0, 28, 5))
    if F_I0OII then
        F_I0OII(...)
    end
end)(...)
